    color: #0d6efd;
}

.radio-option input[type="radio"] {
    accent-color: #0d6efd;
}

/* ── Live preview ───────────────────────────────────────────── */
.live-preview {
    margin-bottom: 24px;
}

.live-preview h5 {
    font-weight: 600;
}

.live-preview p {
    line-height: 1.5;
}

/* ── Buttons ────────────────────────────────────────────────── */
.action-buttons {
    display: flex;
    gap: 10px;
    margin-top: 28px;
    padding-top: 20px;
