                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    @if (_securitySettings?.LastPasswordChange is not null)
                    {
                        <p class="hint-text">Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>
            }
        </div>

        <!-- Two-factor authentication -->
        <div class="toggle-row tfa-row">
            <div>
                <strong>Two-Factor Authentication</strong>
                <p class="toggle-description">Add an extra layer of security to your account</p>
            </div>
            <div class="tfa-status">
                <span class="status-indicator @(_twoFactorEnabled ? "status-on" : "status-off")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <!-- Active sessions -->
        <h4 class="subsection-title">Active Sessions</h4>
        @if (_securitySettings?.Sessions is { Count: > 0 })
        {
            <div class="sessions-table-wrapper">
                <table class="table sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _securitySettings.Sessions)
                        {
                            <tr>
                                <td>
                                    @session.Device
                                    @if (session.Id == CurrentSessionId)
                                    {
                                        <span class="current-badge">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (session.Id != CurrentSessionId)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevokeSession(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        }
        else
        {
            <p class="empty-state">No active sessions found.</p>
        }
    </div>;

    private static string FormatLastActive(DateTime dt)
    {
        var diff = DateTime.UtcNow - dt;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    private RenderFragment RenderAppearanceSection() => @<div class="section-panel">
