            <div class="radio-group">
                @foreach (var fs in _fontSizes)
                {
                    <label class="radio-option @(_fontSize == fs ? "selected" : "")">
                        <input type="radio" name="fontSize" value="@fs"
                               checked="@(_fontSize == fs)"
                               @onchange="() => _fontSize = fs" />
                        <span class="radio-label">@fs</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language dropdown -->
        <div class="form-group">
            <label class="group-label">Language</label>
            <select class="form-select" @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact mode toggle -->
        <div class="toggle-row">
            <div>
                <strong>Compact Mode</strong>
                <p class="toggle-description">Reduce spacing and padding for a denser layout</p>
            </div>
            <label class="switch">
                <input type="checkbox" @bind="_compactMode" />
                <span class="slider"></span>
            </label>
        </div>

        <!-- Live preview -->
        <h4 class="subsection-title">Preview</h4>
        <div class="live-preview" style="background-color: @PreviewBgColor; color: @PreviewTextColor; font-size: @PreviewFontSizeCss; padding: @(_compactMode ? "12px" : "24px"); border-radius: 8px; border: 1px solid #dee2e6; transition: all 0.3s ease;">
            <h5 style="color: @PreviewAccentColor; margin-bottom: @(_compactMode ? "4px" : "12px");">Dashboard</h5>
            <p style="margin-bottom: @(_compactMode ? "4px" : "10px");">This is a preview of how your content will appear with the selected settings.</p>
            <div style="display: flex; gap: @(_compactMode ? "6px" : "12px"); flex-wrap: wrap;">
                <span style="background: @PreviewAccentColor; color: white; padding: @(_compactMode ? "2px 8px" : "6px 16px"); border-radius: 4px;">Button</span>
                <span style="border: 1px solid @PreviewAccentColor; color: @PreviewAccentColor; padding: @(_compactMode ? "2px 8px" : "6px 16px"); border-radius: 4px;">Outline</span>
            </div>
            <p style="margin-top: @(_compactMode ? "6px" : "12px"); opacity: 0.7; font-size: 0.85em;">
                Theme: @_theme · Font: @_fontSize · Language: @_language · Compact: @(_compactMode ? "On" : "Off")
            </p>
        </div>

        <div class="action-buttons">
            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
        </div>
    </div>;
}

/* ── Layout ─────────────────────────────────────────────────── */
.settings-container {
    display: flex;
    min-height: calc(100vh - 70px);
    gap: 0;
}

/* ── Sidebar ────────────────────────────────────────────────── */
.settings-sidebar {
    width: 240px;
    flex-shrink: 0;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 24px 0;
}

.sidebar-title {
    padding: 0 20px 16px;
    margin: 0;
    font-size: 1.1rem;
    font-weight: 600;
    color: #495057;
    border-bottom: 1px solid #dee2e6;
}

.sidebar-nav {
    list-style: none;
    padding: 8px 0;
    margin: 0;
}

.sidebar-nav li {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 20px;
    cursor: pointer;
    color: #495057;
    font-weight: 500;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.sidebar-nav li:hover {
    background: #e9ecef;
    color: #212529;
}

.sidebar-nav li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
}

.nav-icon {
    font-size: 1.15rem;
}

/* ── Content ────────────────────────────────────────────────── */
.settings-content {
    flex: 1;
    padding: 32px 40px;
    max-width: 800px;
    position: relative;
}

.section-panel h2 {
    margin: 0 0 4px;
    font-size: 1.5rem;
    font-weight: 600;
}

.section-description {
    color: #6c757d;
    margin-bottom: 28px;
}

.loading-spinner {
    display: flex;
    justify-content: center;
    padding-top: 80px;
}

/* ── Form elements ──────────────────────────────────────────── */
.form-group {
    margin-bottom: 20px;
}

.form-group label,
.group-label {
    display: block;
    font-weight: 600;
    margin-bottom: 6px;
    color: #343a40;
    font-size: 0.9rem;
}

.form-control,
.form-select {
    max-width: 480px;
}

/* ── Avatar area ────────────────────────────────────────────── */
.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 20px;
    margin-bottom: 24px;
}

.avatar-preview {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    overflow: hidden;
    background: #e9ecef;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 3px solid #dee2e6;
}

.avatar-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 2.5rem;
    color: #adb5bd;
}

.avatar-url-field {
    flex: 1;
    max-width: 380px;
}

.avatar-url-field label {
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 6px;
    display: block;
    color: #343a40;
}

/* ── Toggle switch ──────────────────────────────────────────── */
.switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.slider {
    position: absolute;
    inset: 0;
    background-color: #ccc;
    border-radius: 26px;
    cursor: pointer;
    transition: 0.25s;
}

.slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background: white;
    border-radius: 50%;
    transition: 0.25s;
}

.switch input:checked + .slider {
    background-color: #0d6efd;
}

.switch input:checked + .slider::before {
    transform: translateX(22px);
}

/* ── Toggle rows ────────────────────────────────────────────── */
.toggle-group {
    margin-bottom: 28px;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row:last-child {
    border-bottom: none;
}

.toggle-description {
    margin: 4px 0 0;
    color: #6c757d;
    font-size: 0.85rem;
}

/* ── Channel list ───────────────────────────────────────────── */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin-bottom: 24px;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #f8f9fa;
}

.channel-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #0d6efd;
}

.channel-name {
    flex: 1;
    font-weight: 500;
    color: #495057;
}

.channel-badge {
    font-size: 0.75rem;
    padding: 2px 8px;
    border-radius: 10px;
    background: #e7f1ff;
    color: #0d6efd;
    font-weight: 600;
}

.channel-item input:checked ~ .channel-badge {
    background: #fff3cd;
    color: #856404;
}

/* ── Expandable panel ───────────────────────────────────────── */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    margin-bottom: 20px;
    overflow: hidden;
}

.expandable-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 14px 18px;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 600;
    font-size: 0.95rem;
    color: #343a40;
    transition: background 0.15s;
}

.expandable-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #6c757d;
}

.expandable-body {
    padding: 18px;
    border-top: 1px solid #dee2e6;
}

.hint-text {
    margin-top: 12px;
    font-size: 0.85rem;
    color: #6c757d;
}

/* ── TFA row ────────────────────────────────────────────────── */
.tfa-row {
    margin-bottom: 24px;
    padding: 16px;
    border: 1px solid #dee2e6;
    border-radius: 8px;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 12px;
}

.status-indicator {
    font-size: 0.8rem;
    font-weight: 600;
    padding: 3px 10px;
    border-radius: 12px;
}

.status-on {
    background: #d1e7dd;
    color: #0f5132;
}

.status-off {
    background: #f8d7da;
    color: #842029;
}

/* ── Sessions table ─────────────────────────────────────────── */
.subsection-title {
    margin: 28px 0 14px;
    font-size: 1.05rem;
    font-weight: 600;
}

.sessions-table-wrapper {
    overflow-x: auto;
}

.sessions-table {
    font-size: 0.9rem;
}

.sessions-table th {
    font-weight: 600;
    color: #6c757d;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.5px;
    border-bottom-width: 2px;
}

.current-badge {
    display: inline-block;
    font-size: 0.7rem;
    padding: 1px 7px;
    margin-left: 8px;
    border-radius: 10px;
    background: #d1e7dd;
    color: #0f5132;
    font-weight: 600;
    vertical-align: middle;
}

.empty-state {
    color: #6c757d;
    font-style: italic;
    padding: 16px 0;
}

/* ── Radio group ────────────────────────────────────────────── */
.radio-group {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.radio-option {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 10px 18px;
    border: 2px solid #dee2e6;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s;
    font-weight: 500;
}

.radio-option:hover {
    border-color: #adb5bd;
}

.radio-option.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
    color: #0d6efd;
}

.radio-option input[type="radio"] {
    accent-color: #0d6efd;
}

/* ── Live preview ───────────────────────────────────────────── */
.live-preview {
    margin-bottom: 24px;
}

.live-preview h5 {
    font-weight: 600;
}

.live-preview p {
    line-height: 1.5;
}

/* ── Buttons ────────────────────────────────────────────────── */
.action-buttons {
    display: flex;
    gap: 10px;
    margin-top: 28px;
    padding-top: 20px;
    border-top: 1px solid #dee2e6;
}

/* ── Toast ──────────────────────────────────────────────────── */
.toast-notification {
    position: fixed;
    bottom: 24px;
    right: 24px;
    padding: 14px 20px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    gap: 12px;
    font-weight: 500;
    box-shadow: 0 4px 16px rgba(0,0,0,0.15);
    z-index: 1100;
    animation: slideUp 0.3s ease;
}

.toast-success {
    background: #0f5132;
    color: white;
}

.toast-error {
    background: #842029;
    color: white;
}

.toast-close {
    background: none;
    border: none;
    color: inherit;
    opacity: 0.7;
    cursor: pointer;
    font-size: 1rem;
    padding: 0;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideUp {
    from { transform: translateY(20px); opacity: 0; }
    to   { transform: translateY(0);    opacity: 1; }
}

/* ── Modal / confirm dialog ─────────────────────────────────── */
.modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

.modal-dialog {
    background: white;
    border-radius: 12px;
    padding: 28px;
    max-width: 440px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0,0,0,0.2);
}

.modal-dialog h4 {
    margin: 0 0 12px;
}

.modal-dialog p {
    color: #495057;
    line-height: 1.5;
}

.modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 20px;
}

