{"file_text": "@page "/settings"
@using sv_d4965890bd8a4e6b9f56e5ac8001a435.Models
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h3 class="sidebar-title">Settings</h3>
        <ul class="sidebar-nav">
            @foreach (var section in _sections)
            {
                <li class="@(_activeSection == section.Key ? "active" : "")"
                    @onclick="() => SetActiveSection(section.Key)">
                    <span class="nav-icon">@section.Value.Icon</span>
                    <span>@section.Value.Label</span>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="loading-spinner">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (_activeSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toastMessage))
        {
            <div class="toast-notification @(_toastIsError ? "toast-error" : "toast-success")">
                <span>@_toastMessage</span>
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </div>
</div>

<!-- Session revoke confirmation dialog -->
@if (_showRevokeDialog)
{
    <div class="modal-backdrop" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <h4>Revoke Session</h4>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong>?
               This will sign out that device immediately.</p>
            <div class="modal-actions">
                <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
            </div>
        </div>
    </div>
}

@code {
    // ── Section navigation ──────────────────────────────────────────
    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨")
    };

    private string _activeSection = "profile";
    private bool _loading = true;

    // ── Toast ───────────────────────────────────────────────────────
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // ── Profile state ───────────────────────────────────────────────
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // ── Notification state ──────────────────────────────────────────
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["announcements", "random", "off-topic", "watercooler"];
    private HashSet<string> _mutedChannels = [];

    // ── Security state ──────────────────────────────────────────────
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;
    private const string CurrentSessionId = "sess-1";

    // ── Appearance state ────────────────────────────────────────────
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _themes = ["Light", "Dark", "System"];
    private readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Portuguese"];

    // ── Lifecycle ───────────────────────────────────────────────────
    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

        ApplyProfile(await profileTask);
        ApplyNotifications(await notifsTask);
        ApplySecuritySettings(await securityTask);
        ApplyAppearance(await appearanceTask);
    }

    private void ApplyProfile(UserProfile p)
    {
        _savedProfile = p;
        _displayName = p.DisplayName;
        _email = p.Email;
        _avatarUrl = p.AvatarUrl;
        _bio = p.Bio;
    }

    private void ApplyNotifications(NotificationPrefs n)
    {
        _emailNotifications = n.EmailNotifications;
        _pushNotifications = n.PushNotifications;
        _weeklyDigest = n.WeeklyDigest;
        _mutedChannels = [..n.MutedChannels];
    }

    private void ApplySecuritySettings(SecuritySettings s)
    {
        _securitySettings = s;
        _twoFactorEnabled = s.TwoFactorEnabled;
    }

    private void ApplyAppearance(AppearanceSettings a)
    {
        _theme = a.Theme;
        _fontSize = a.FontSize;
        _language = a.Language;
        _compactMode = a.CompactMode;
    }

    private void SetActiveSection(string section)
    {
        _activeSection = section;
        DismissToast();
    }

    // ── Toast helpers ───────────────────────────────────────────────
    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastCts = new CancellationTokenSource();
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        try
        {
            await Task.Delay(4000, _toastCts.Token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        _toastCts?.Cancel();
        _toastMessage = null;
    }

    // ── Profile actions ─────────────────────────────────────────────
    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // ── Notification actions ────────────────────────────────────────
    private bool IsChannelMuted(string channel) => _mutedChannels.Contains(channel);

    private void ToggleChannelMute(string channel, ChangeEventArgs e)
    {
        if (e.Value is true)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _emailNotifications, _pushNotifications, _weeklyDigest,
            _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // ── Security actions ────────────────────────────────────────────
    private void ToggleChangePassword() => _changePasswordExpanded = !_changePasswordExpanded;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("Password must be at least 8 characters.", true);
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _changePasswordExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        await ShowToast("Password updated successfully!");
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeDialog = false;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        }
        _showRevokeDialog = false;
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    // ── Appearance actions ──────────────────────────────────────────
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    private string PreviewFontSizeCss => _fontSize switch
    {
        "Small" => "13px",
        "Large" => "18px",
        _ => "15px"
    };

    private string PreviewBgColor => _theme switch
    {
        "Dark" => "#1e1e2e",
        _ => "#ffffff"
    };

    private string PreviewTextColor => _theme switch
    {
        "Dark" => "#cdd6f4",
        _ => "#1e1e2e"
    };

    private string PreviewAccentColor => _theme switch
    {
        "Dark" => "#89b4fa",
        _ => "#0d6efd"
    };

    // ── Render fragments ────────────────────────────────────────────
    private RenderFragment RenderProfileSection() => @<div class="section-panel">
        <h2>Profile</h2>
        <p class="section-description">Manage your public profile information.</p>

        <div class="avatar-area">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                {
                    <img src="@_avatarUrl" alt="Avatar" />
                }
                else
                {
                    <div class="avatar-placeholder">👤</div>
                }
            </div>
            <div class="avatar-url-field">
                <label>Avatar URL</label>
                <input type="url" class="form-control" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
            </div>
        </div>

        <div class="form-group">
            <label>Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label>Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>

        <div class="form-group">
            <label>Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>

        <div class="action-buttons">
            <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
        </div>
    </div>;

    private RenderFragment RenderNotificationsSection() => @<div class="section-panel">
        <h2>Notifications</h2>
        <p class="section-description">Control how and when you receive notifications.</p>

        <div class="toggle-group">
            <div class="toggle-row">
                <div>
                    <strong>Email Notifications</strong>
                    <p class="toggle-description">Receive notifications via email</p>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="slider"></span>
                </label>
            </div>

            <div class="toggle-row">
                <div>
                    <strong>Push Notifications</strong>
                    <p class="toggle-description">Receive push notifications in your browser</p>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="slider"></span>
                </label>
            </div>

            <div class="toggle-row">
                <div>
                    <strong>Weekly Digest</strong>
                    <p class="toggle-description">Get a weekly summary of activity</p>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="slider"></span>
                </label>
            </div>
        </div>

        <h4 class="subsection-title">Muted Channels</h4>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@IsChannelMuted(channel)"
                           @onchange="e => ToggleChannelMute(channel, e)" />
                    <span class="channel-name">#@channel</span>
                    <span class="channel-badge">@(IsChannelMuted(channel) ? "Muted" : "Active")</span>
                </label>
            }
        </div>

        <div class="action-buttons">
            <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
        </div>
    </div>;

    private RenderFragment RenderSecuritySection() => @<div class="section-panel">
        <h2>Security</h2>
        <p class="section-description">Manage your account security and active sessions.</p>

        <!-- Change password expandable panel -->
        <div class="expandable-panel">
            <button class="expandable-header" @onclick="ToggleChangePassword">
                <span>🔑 Change Password</span>
                <span class="expand-icon">@(_changePasswordExpanded ? "▲" : "▼")</span>
            </button>
            @if (_changePasswordExpanded)
            {
                <div class="expandable-body">
                    <div class="form-group">
                        <label>Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label>New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
