            <div style="display: flex; gap: @(_compactMode ? "6px" : "12px"); flex-wrap: wrap;">
                <span style="background: @PreviewAccentColor; color: white; padding: @(_compactMode ? "2px 8px" : "6px 16px"); border-radius: 4px;">Button</span>
                <span style="border: 1px solid @PreviewAccentColor; color: @PreviewAccentColor; padding: @(_compactMode ? "2px 8px" : "6px 16px"); border-radius: 4px;">Outline</span>
