+}
+
+.live-preview h5 {
+    font-weight: 600;
+}
+
+.live-preview p {
+    line-height: 1.5;
+}
+
+/* ── Buttons ────────────────────────────────────────────────── */
+.action-buttons {
+    display: flex;
+    gap: 10px;
+    margin-top: 28px;
+    padding-top: 20px;
+    border-top: 1px solid #dee2e6;
+}
+
+/* ── Toast ──────────────────────────────────────────────────── */
+.toast-notification {
+    position: fixed;
+    bottom: 24px;
+    right: 24px;
+    padding: 14px 20px;
+    border-radius: 8px;
